-- AnimeWiki PostgreSQL database schema
-- Run as a PostgreSQL superuser (e.g. postgres).

CREATE DATABASE anime_wiki;

\connect anime_wiki;

CREATE TABLE IF NOT EXISTS "Anime" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "AniListId" integer NOT NULL,
    "Title" text NOT NULL,
    "OriginalTitle" text NULL,
    "Description" text NULL,
    "Episodes" integer NULL,
    "Rating" double precision NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS "IX_Anime_AniListId"
    ON "Anime" ("AniListId");

CREATE TABLE IF NOT EXISTS "Genres" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" text NOT NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS "IX_Genres_Name"
    ON "Genres" ("Name");

CREATE TABLE IF NOT EXISTS "Characters" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "AniListId" integer NOT NULL,
    "Name" text NOT NULL,
    "ImageUrl" text NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS "IX_Characters_AniListId"
    ON "Characters" ("AniListId");

CREATE TABLE IF NOT EXISTS "AnimeGenre" (
    "AnimeId" integer NOT NULL,
    "GenreId" integer NOT NULL,
    CONSTRAINT "PK_AnimeGenre" PRIMARY KEY ("AnimeId", "GenreId"),
    CONSTRAINT "FK_AnimeGenre_Anime_AnimeId"
        FOREIGN KEY ("AnimeId") REFERENCES "Anime" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_AnimeGenre_Genres_GenreId"
        FOREIGN KEY ("GenreId") REFERENCES "Genres" ("Id") ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS "IX_AnimeGenre_GenreId"
    ON "AnimeGenre" ("GenreId");

CREATE TABLE IF NOT EXISTS "AnimeCharacter" (
    "AnimeId" integer NOT NULL,
    "CharacterId" integer NOT NULL,
    CONSTRAINT "PK_AnimeCharacter" PRIMARY KEY ("AnimeId", "CharacterId"),
    CONSTRAINT "FK_AnimeCharacter_Anime_AnimeId"
        FOREIGN KEY ("AnimeId") REFERENCES "Anime" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_AnimeCharacter_Characters_CharacterId"
        FOREIGN KEY ("CharacterId") REFERENCES "Characters" ("Id") ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS "IX_AnimeCharacter_CharacterId"
    ON "AnimeCharacter" ("CharacterId");

-- Таблиця користувачів (той самий безпечний скрипт для наявної БД).
-- Додає лише авторизацію до ІСНУЮЧОЇ anime_wiki БД.
-- Запустити в БД anime_wiki через DBeaver / psql за потреби.
-- Існуючі аніме, жанри й персонажі не змінюються.
CREATE TABLE IF NOT EXISTS "Users" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Username" character varying(50) NOT NULL,
    "NormalizedUsername" character varying(50) NOT NULL,
    "Email" character varying(256) NOT NULL,
    "NormalizedEmail" character varying(256) NOT NULL,
    "PasswordHash" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Users" PRIMARY KEY ("Id")
);

CREATE UNIQUE INDEX IF NOT EXISTS "IX_Users_NormalizedEmail"
    ON "Users" ("NormalizedEmail");
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Users_NormalizedUsername"
    ON "Users" ("NormalizedUsername");
